params.command:
$ErrorActionPreference='Continue'
$repo='C:\Users\Xxkan\mhw-mods-work-canonical'
git -C $repo fetch origin --prune | Out-Host
$targets=@('agent/bridge-priority-scheduler-20260929','integration/bridge-priority-aging-main-20260929','integration/bridge-priority-aging-main-r2-20260929','agent/game-profile-id-containment-20260928','agent/game-profile-id-containment-v2-20260928','agent/game-profile-id-containment-v8.8.5-reconcile','feature/agent-control-panel-20260928','feature/agent-command-center-20260928','ui/frontend-responsive-polish-20260928','ui/frontend-ux-overhaul','support/updater-publication-input-scope-20260928','agent/updater-installed-e2e-20260929-manager','agent/programmer-updater-rest-handoff-20260928','agent/reconciliation-continuity-20260929-0542-github','agent/reconciliation-continuity-20260929-final-github','agent/reconciliation-continuity-20260929-r3','agent/support-continuity-drift-reconciliation-20260928','agent/support-continuity-drift-repair-20260928','agent/support-pr-disposition-ledger-20260928','agent/v881-updater-publication-handoff-20260928','agent/support-agent-control-v2-product-workflow-audit-20260928','agent/support-archive-streaming-failure-cleanup-audit-20260928','agent/support-auto-updater-release-security-audit-20260928','agent/support-auto-updater-runtime-recovery-audit-20260928','agent/support-updater-c10-manager-review-20260928','agent/support-updater-lr003-restart-audit-20260928','agent/support-updater-packaging-audit-20260928','agent/support-updater-wpf-integration-audit-20260928','agent/replacefilew-failure-characterization-20260927')
$active=@()
foreach($line in @(git -C $repo worktree list --porcelain)){
  if($line -like 'branch refs/heads/*'){ $active += $line.Substring(18) }
}
$deleted=@();$skipped=@();$missing=@();$failed=@()
foreach($b in $targets){
  git -C $repo show-ref --verify --quiet ("refs/remotes/origin/"+$b)
  if($LASTEXITCODE -ne 0){$missing+=$b;continue}
  if($b -in $active){$skipped += "$b|active-worktree";continue}
  & git -C $repo push origin --delete $b 2>&1 | Out-Host
  if($LASTEXITCODE -eq 0){$deleted+=$b}else{$failed+=$b}
}
git -C $repo fetch origin --prune | Out-Null
$remaining=@(git -C $repo for-each-ref --format='%(refname:short)' refs/remotes/origin | Where-Object {$_ -ne 'origin/HEAD'})
[pscustomobject]@{deleted=$deleted;deleted_count=$deleted.Count;skipped=$skipped;missing=$missing;failed=$failed;remaining_count=$remaining.Count;main=(git -C $repo rev-parse origin/main).Trim()} | ConvertTo-Json -Depth 5
